<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import UButton from '@nuxt/ui/components/Button.vue';
import UInput from '@nuxt/ui/components/Input.vue';
import UModal from '@nuxt/ui/components/Modal.vue';
import UCheckbox from '@nuxt/ui/components/Checkbox.vue';
import UIcon from '@nuxt/ui/components/Icon.vue';
import USwitch from '@nuxt/ui/components/Switch.vue';
import { pickFile, pickFolder, scanPaths } from '@/lib/tauri';
import { LAUNCHER_PANEL_KEY, launcherEntries, launchEntries, operationResults, pinEntry, rebindLauncher, reorderLauncher, scheduleSave, setLauncherVisible, showStatus, store, toggleLauncher } from '@/stores/state';
const missing = ref<string[]>([]), query=ref(''), collectionOpen=ref(false), collectionName=ref(''), editingCollection=ref(''), members=ref<string[]>([]), busy=ref(false);
const entries=computed(()=>launcherEntries.value.filter(e=>e.name.toLowerCase().includes(query.value.toLowerCase())));
async function check(){try{const physical=launcherEntries.value.filter(e=>e.launchKind==='filesystem');const found=await scanPaths(physical.map(e=>e.path));const paths=new Set(found.map(e=>e.path.toLowerCase()));missing.value=physical.filter(e=>!paths.has(e.path.toLowerCase())).map(e=>e.id)}catch(e){showStatus(`检查入口失败：${e}`)}}
async function add(oldId?:string,folder=false){try{const path=folder?await pickFolder():await pickFile();if(!path)return;const entry=(await scanPaths([path]))[0];if(!entry)throw new Error('文件不可访问');oldId?rebindLauncher(oldId,entry):pinEntry(entry);await check()}catch(e){showStatus(`无法添加入口：${e}`)}}
function createCollection(){if(!collectionName.value.trim())return;const collection=store.launchCollections.find(c=>c.id===editingCollection.value);if(collection)Object.assign(collection,{name:collectionName.value.trim(),entryIds:[...members.value]});else store.launchCollections.push({id:crypto.randomUUID(),name:collectionName.value.trim(),entryIds:[...members.value]});scheduleSave();collectionOpen.value=false;}
async function launch(ids:string[]){busy.value=true;try{await launchEntries(ids.map(id=>launcherEntries.value.find(e=>e.id===id)).filter((e):e is NonNullable<typeof e>=>Boolean(e)))}finally{busy.value=false}}
onMounted(check);
</script>
<template>
<div class="page-heading"><div><h1>快捷启动</h1><p>固定常用应用与文件，按工作场景批量打开。</p></div><UButton icon="i-lucide-plus" @click="add()">添加入口</UButton></div>
<div class="manager-card settings-row"><div><h2>桌面启动栏</h2><p>固定的入口只保存引用，原文件不移动。显示时保留原来的位置。</p></div><div class="flex items-center gap-3"><USwitch :model-value="store.panelLayouts[LAUNCHER_PANEL_KEY]?.visible===true&&!store.paused" aria-label="在桌面显示启动栏" @update:model-value="setLauncherVisible"/><UButton variant="outline" size="sm" @click="setLauncherVisible(true)">查看启动栏</UButton></div></div>
<div class="page-toolbar"><UInput v-model="query" icon="i-lucide-search" placeholder="筛选快捷入口"/><UButton variant="outline" @click="add(undefined,true)">添加文件夹</UButton><UButton variant="outline" @click="check">检查可用性</UButton><UButton variant="outline" :loading="busy" :disabled="!store.launcherIds.length" @click="launch(store.launcherIds)">启动全部</UButton></div>
<div class="manager-card"><div v-for="entry in entries" :key="entry.id" class="source-row"><div class="source-icon"><UIcon :name="entry.isApplication?'i-lucide-app-window':'i-lucide-file'"/></div><div class="row-content"><UInput :model-value="entry.name" aria-label="入口显示名称" variant="none" @change="event=>{store.launcherReferences[entry.id]={...entry,name:(event.target as HTMLInputElement).value||entry.name};scheduleSave()}"/><small>{{entry.path}}</small><p v-if="missing.includes(entry.id)" class="error-text">目标失联，入口已保留。可重新绑定或移除引用。</p></div><UButton variant="ghost" size="sm" aria-label="向前移动" :disabled="store.launcherIds[0]===entry.id" @click="reorderLauncher(entry.id,-1)">↑</UButton><UButton variant="ghost" size="sm" aria-label="向后移动" :disabled="store.launcherIds.at(-1)===entry.id" @click="reorderLauncher(entry.id,1)">↓</UButton><UButton v-if="missing.includes(entry.id)" size="sm" variant="outline" @click="add(entry.id)">重新绑定</UButton><UButton v-else size="sm" variant="outline" :loading="busy" @click="launch([entry.id])">打开</UButton><UButton color="neutral" variant="ghost" size="sm" @click="toggleLauncher(entry.id)">移除引用</UButton></div><div v-if="!entries.length" class="manager-empty"><UIcon name="i-lucide-rocket"/><h3>把常用入口放在手边</h3><p>在搜索结果中固定应用，或添加一个本机文件。</p><UButton variant="outline" @click="add()">添加入口</UButton></div></div>
<div class="manager-card"><div class="card-heading"><h2>启动集合</h2><UButton variant="ghost" size="sm" :disabled="!store.launcherIds.length" @click="editingCollection='';collectionName='';members=[];collectionOpen=true">新建集合</UButton></div><div v-for="collection in store.launchCollections" :key="collection.id" class="source-row"><div class="row-content"><UInput v-model="collection.name" aria-label="集合名称" @change="scheduleSave"/><small>{{collection.entryIds.length}} 个入口 · {{collection.entryIds.map(id=>launcherEntries.find(e=>e.id===id)?.name??'失联入口').join('、')}}</small></div><UButton variant="outline" :loading="busy" @click="launch(collection.entryIds)">启动集合</UButton><UButton variant="ghost" @click="editingCollection=collection.id;collectionName=collection.name;members=[...collection.entryIds];collectionOpen=true">编辑成员</UButton><UButton variant="ghost" color="error" @click="store.launchCollections=store.launchCollections.filter(c=>c.id!==collection.id);scheduleSave()">移除集合</UButton></div><p v-if="!store.launchCollections.length" class="card-note">例如为“开发工作”组合编辑器、浏览器和项目文档。</p></div>
<div v-if="operationResults.length" class="manager-card"><div class="card-heading"><h2>本次启动结果</h2></div><div v-for="result in operationResults" :key="result.path" class="plan-row" :class="{'error-text':!result.ok}"><strong>{{result.name}} · {{result.ok?'已打开':'失败'}}</strong><small>{{result.message}}</small></div></div>
<UModal v-model:open="collectionOpen" :title="editingCollection?'编辑启动集合':'新建启动集合'" description="集合只保存入口引用。"><template #body><div class="form-stack"><UInput v-model="collectionName" placeholder="集合名称"/><UCheckbox v-for="entry in launcherEntries" :key="entry.id" :label="entry.name" :model-value="members.includes(entry.id)" @update:model-value="v=>members=v?[...members,entry.id]:members.filter(id=>id!==entry.id)"/></div></template><template #footer><UButton :disabled="!collectionName.trim()||!members.length" @click="createCollection">{{editingCollection?'保存集合':'创建集合'}}</UButton></template></UModal>
</template>
